        # self.prior_gru  = nn.GRU(nm_a, prior_h, 1, batch_first=True)
        # self.prior_gru  = nn.GRU(nm_a, prior_h, 1, batch_first=True)
        self.prior_proj = nn.Linear(prior_h*nsep, nm*nm_a,bias=True)
