        sep = (high - low)/nsep

        ### quantised variable
        ### ns*b,m
        xz_int = (xz.clip(low,high-0.001) - low)//sep
        xz_noise_new = (xz_int)*sep + low


        prior_logsigma = torch.tensor(math.log(0.5),device=x.device)
