        ## b,t
        lpe = -0.5*invsqsigma*(xz - xz.clip(low,high)).square().sum(-1)

        xz_noise = (xz_noise_new - xz).detach() + xz + (torch.rand_like(xz)-0.5)*sep
        
        lpz = math.log(1./nsep) + torch.zeros_like(xz_noise)
        lpz = lpz.sum(-1)

        _disabled = 0
