        # post_logsigma  = self.post_logsigma.clip(None,math.log(rd/6.))
        # post_invsqsigma = 1./(2*post_logsigma).exp()


        low = -1.0
        high = 1.0
        nsep = 50
        nsep = 100

        low = -3.0
        high = 3.0
        nsep = 50
        # nsep = 100

