        self.logsigma = math.log(1.0)
        # self.logsigma = math.log(0.2)  ## R3

        self.mode=0  ### compute PAE loss mode
        # self.mode=1  ### disable latent
        self.mode=10  ### disable latent
        # self.mode=2  ### disable prior
        self.mode=3  ### use prior avereage for latent, and disable latent loss. use pure AR loss

